'use client'

import { FormEvent, useCallback, useEffect, useMemo, useRef, useState } from 'react'
import type { LucideIcon } from 'lucide-react'
import { Activity, AlertTriangle, BarChart3, Bell, Boxes, Building2, Check, ChevronRight, CircleDollarSign, ClipboardList, FileText, LayoutDashboard, Loader2, LogOut, MapPin, Menu, Package, PanelLeftClose, PanelLeftOpen, Plus, RefreshCw, Route, Save, Search, Settings, ShoppingCart, Terminal, Trash2, Truck, UserRound, UserPlus, Users, X } from 'lucide-react'
import { ApiError, adminLogin, apiFetch, getAdminToken, setAdminToken, websocketUrl } from '@/lib/api'

type AnyRecord = Record<string, any>
type SectionId = 'dashboard' | 'operations' | 'orders' | 'catalog' | 'inventory' | 'sales' | 'customers' | 'drivers' | 'promotions' | 'settings' | 'owner-console'
type AdminUser = AnyRecord & { id: number; username: string; role: string; full_name?: string }
type Product = AnyRecord & { id: number; name: string; price: number; stock?: number; min_stock?: number; active?: boolean }
type Order = AnyRecord & { id: number | string; total: number; status?: string; user_full_name?: string; user_email?: string }

declare global {
  interface Window { google?: any; __distriarGoogleMapsPromise?: Promise<any> }
}

const nav: { id: SectionId; label: string; icon: LucideIcon; group: string; ownerOnly?: boolean }[] = [
  { id: 'dashboard', label: 'Resumen', icon: LayoutDashboard, group: 'GENERAL' },
  { id: 'operations', label: 'Operaciones', icon: Activity, group: 'GENERAL' },
  { id: 'orders', label: 'Pedidos y asignaciones', icon: ClipboardList, group: 'GESTIÓN COMERCIAL' },
  { id: 'sales', label: 'Ventas', icon: CircleDollarSign, group: 'GESTIÓN COMERCIAL' },
  { id: 'catalog', label: 'Productos y catálogo', icon: Package, group: 'GESTIÓN COMERCIAL' },
  { id: 'inventory', label: 'Inventario y stock', icon: Boxes, group: 'GESTIÓN COMERCIAL' },
  { id: 'promotions', label: 'Promociones y consumos', icon: FileText, group: 'GESTIÓN COMERCIAL' },
  { id: 'customers', label: 'Clientes y cuentas', icon: Users, group: 'RELACIONES' },
  { id: 'drivers', label: 'Repartidores y mapa', icon: Truck, group: 'RELACIONES' },
  { id: 'settings', label: 'Usuarios y sucursales', icon: Settings, group: 'CONFIGURACIÓN' },
  { id: 'owner-console', label: 'Consola del owner', icon: Terminal, group: 'CONFIGURACIÓN', ownerOnly: true },
]

const statusLabels: Record<string, string> = { recibido: 'Recibido', visto: 'Visto', preparado: 'Preparado', enviado: 'Enviado', entregado: 'Entregado', cancelado: 'Cancelado' }
const mapsKey = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY || ''

function asArray(value: any): any[] { return Array.isArray(value) ? value : [] }
function money(value: any) { return new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS', maximumFractionDigits: 0 }).format(Number(value) || 0) }
function date(value: any) { if (!value) return '—'; const parsed = new Date(value); return Number.isNaN(parsed.getTime()) ? String(value) : parsed.toLocaleString('es-AR', { dateStyle: 'short', timeStyle: 'short' }) }
function statusTone(value: string) { return value === 'entregado' ? 'green' : value === 'cancelado' ? 'red' : value === 'enviado' ? 'blue' : value === 'preparado' ? 'violet' : 'amber' }
function errorMessage(error: unknown, fallback: string) { return error instanceof ApiError ? `${error.detail} (HTTP ${error.status})` : error instanceof Error ? error.message : fallback }

function Card({ children, className = '' }: { children: React.ReactNode; className?: string }) { return <section className={`rounded-2xl border border-slate-200 bg-white shadow-[0_1px_2px_rgba(15,23,42,.03)] ${className}`}>{children}</section> }
function Pill({ children, tone = 'gray' }: { children: React.ReactNode; tone?: string }) { const tones: Record<string, string> = { green: 'bg-emerald-50 text-emerald-700', red: 'bg-red-50 text-red-700', blue: 'bg-blue-50 text-blue-700', violet: 'bg-violet-50 text-violet-700', amber: 'bg-amber-50 text-amber-700', gray: 'bg-slate-100 text-slate-600' }; return <span className={`inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1 text-[11px] font-semibold ${tones[tone] || tones.gray}`}><span className="size-1.5 rounded-full bg-current" />{children}</span> }
function Metric({ label, value, detail, icon: Icon, tone = 'green' }: { label: string; value: string; detail?: string; icon: LucideIcon; tone?: string }) { const iconTone: Record<string, string> = { green: 'bg-emerald-50 text-emerald-600', blue: 'bg-blue-50 text-blue-600', amber: 'bg-amber-50 text-amber-600', red: 'bg-red-50 text-red-600', violet: 'bg-violet-50 text-violet-600' }; return <Card className="p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-slate-500">{label}</p><p className="mt-2 text-2xl font-bold tracking-tight text-slate-900">{value}</p></div><span className={`flex size-10 items-center justify-center rounded-xl ${iconTone[tone] || iconTone.green}`}><Icon className="size-5" /></span></div>{detail && <p className="mt-3 text-xs text-slate-500">{detail}</p>}</Card> }
function Empty({ message = 'No hay datos para mostrar.' }: { message?: string }) { return <div className="flex min-h-32 items-center justify-center p-8 text-sm text-slate-500">{message}</div> }
function PageTitle({ title, description, action }: { title: string; description: string; action?: React.ReactNode }) { return <div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-2xl font-bold tracking-tight text-slate-900">{title}</h2><p className="mt-1 text-sm text-slate-500">{description}</p></div>{action}</div> }
function Field({ label, value, onChange, type = 'text', required = false, placeholder = '' }: { label: string; value: any; onChange: (value: string) => void; type?: string; required?: boolean; placeholder?: string }) { return <label className="block text-sm font-medium text-slate-700">{label}<input required={required} type={type} value={value ?? ''} placeholder={placeholder} onChange={event => onChange(event.target.value)} className="field mt-1.5" /></label> }

function Login({ onLoggedIn }: { onLoggedIn: (user: AdminUser) => void }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [scope, setScope] = useState('mayorista'); const [error, setError] = useState(''); const [loading, setLoading] = useState(false)
  async function submit(event: FormEvent) { event.preventDefault(); setLoading(true); setError(''); try { await adminLogin(username, password, scope); onLoggedIn(await apiFetch<AdminUser>('/admin/auth/me', { businessScope: scope })) } catch (e) { setError(errorMessage(e, 'No se pudo iniciar sesión')) } finally { setLoading(false) } }
  return <main className="flex min-h-screen items-center justify-center bg-slate-50 p-5"><Card className="w-full max-w-md p-8"><div className="mb-8 flex items-center gap-3"><span className="flex size-11 items-center justify-center rounded-xl bg-emerald-600 text-xl font-bold text-white">D</span><div><p className="text-xl font-bold text-slate-900">Distri<span className="text-emerald-600">Ar</span></p><p className="text-xs uppercase tracking-widest text-slate-400">Panel administrativo</p></div></div><h1 className="text-2xl font-bold text-slate-900">Iniciar sesión</h1><p className="mt-1 text-sm text-slate-500">Accedé a las operaciones de tu rubro.</p><form onSubmit={submit} className="mt-7 space-y-4"><Field label="Usuario" value={username} onChange={setUsername} required /><Field label="Contraseña" value={password} onChange={setPassword} type="password" required /><label className="block text-sm font-medium text-slate-700">Rubro<select value={scope} onChange={event => setScope(event.target.value)} className="field mt-1.5"><option value="mayorista">Mayorista</option><option value="minorista">Minorista</option></select></label>{error && <p className="rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>}<button disabled={loading} className="primary-button w-full">{loading && <Loader2 className="size-4 animate-spin" />}{loading ? 'Ingresando…' : 'Ingresar al panel'}</button></form></Card></main>
}

function OrderTable({ orders, drivers, onStatus, onAssign }: { orders: Order[]; drivers?: AdminUser[]; onStatus?: (order: Order, status: string) => void; onAssign?: (order: Order, driverId: string) => void }) {
  return <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Importe</th><th>Estado</th><th>Repartidor</th><th>Fecha</th><th /></tr></thead><tbody>{orders.length ? orders.map(order => <tr key={String(order.id)}><td className="font-semibold text-slate-800">#{order.id}</td><td><p className="font-medium text-slate-700">{order.user_full_name || 'Cliente'}</p><p className="text-[11px] text-slate-400">{order.user_email || order.customer_type || '—'}</p></td><td className="font-semibold">{money(order.total)}</td><td><Pill tone={statusTone(String(order.status || 'recibido'))}>{statusLabels[order.status || 'recibido'] || order.status || 'Recibido'}</Pill></td><td>{onAssign && drivers?.length ? <select value={String(order.assigned_driver_id || '')} onChange={event => onAssign(order, event.target.value)} className="max-w-44 rounded-lg border border-slate-200 bg-white px-2 py-1.5 text-xs"><option value="">Sin asignar</option>{drivers.map(driver => <option key={driver.id} value={driver.id}>{driver.full_name || driver.username}</option>)}</select> : <span className="text-xs text-slate-500">{order.assigned_driver_name || order.assigned_driver_username || 'Sin asignar'}</span>}</td><td className="text-slate-500">{date(order.created_at)}</td><td>{onStatus && <select value={order.status || 'recibido'} onChange={event => onStatus(order, event.target.value)} className="rounded-lg border border-slate-200 bg-white px-2 py-1.5 text-xs"><option value="recibido">Recibido</option><option value="visto">Visto</option><option value="preparado">Preparado</option><option value="enviado">Enviado</option><option value="entregado">Entregado</option><option value="cancelado">Cancelado</option></select>}</td></tr>) : <tr><td colSpan={7}><Empty message="No hay pedidos que coincidan." /></td></tr>}</tbody></table></div>
}

function Dashboard({ data, orders, onSection }: { data: AnyRecord; orders: Order[]; onSection: (id: SectionId) => void }) {
  const kpis = data?.kpis || {}; const orderKpis = kpis.orders || {}; const salesKpis = kpis.sales || {}; const catalog = kpis.catalog || {}; const byStatus = orderKpis.by_status || orderKpis.status_counts || {}; const series = asArray(data?.sales?.by_day || data?.by_day); const max = Math.max(1, ...series.map(item => Number(item?.revenue || item?.total || item?.value || 0)))
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-sm text-slate-500">{new Date().toLocaleDateString('es-AR', { dateStyle: 'full' })}</p><h2 className="mt-1 text-2xl font-bold tracking-tight text-slate-900">Resumen operativo</h2><p className="mt-1 text-sm text-slate-500">Datos reales del backend y actividad del panel.</p></div><button onClick={() => onSection('operations')} className="secondary-button"><Activity className="size-4" />Ver operaciones</button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Ventas del período" value={money(salesKpis.revenue_30d ?? salesKpis.revenue ?? 0)} detail={`${salesKpis.orders_30d ?? salesKpis.orders ?? 0} pedidos`} icon={CircleDollarSign} /><Metric label="Pedidos" value={String(orderKpis.total ?? orderKpis.count ?? orders.length ?? 0)} detail="Muestra operativa actual" icon={ShoppingCart} tone="blue" /><Metric label="Ticket promedio" value={money(salesKpis.avg_ticket ?? 0)} detail="Calculado por el backend" icon={ClipboardList} tone="amber" /><Metric label="Stock bajo" value={String(catalog.low_stock_count ?? catalog.low_stock ?? 0)} detail="Requieren reposición" icon={AlertTriangle} tone="red" /></div><div className="grid gap-5 xl:grid-cols-[1.55fr_.9fr]"><Card className="p-5"><div className="flex items-center justify-between"><div><h3 className="section-title">Evolución de ventas</h3><p className="muted">Ingresos del período seleccionado</p></div><BarChart3 className="size-5 text-emerald-600" /></div>{series.length ? <div className="mt-8 flex h-52 items-end gap-1.5 border-b border-slate-200">{series.map((item, index) => { const amount = Number(item?.revenue || item?.total || item?.value || 0); return <div key={index} className="group flex h-full flex-1 items-end"><div title={`${item?.date || item?.day || ''} ${money(amount)}`} style={{ height: `${Math.max(3, amount / max * 100)}%` }} className="w-full rounded-t bg-emerald-200 transition-colors group-hover:bg-emerald-500" /></div> })}</div> : <Empty message="El backend todavía no devolvió una serie diaria." />}</Card><Card className="p-5"><h3 className="section-title">Pedidos por estado</h3><p className="muted">Distribución actual de pedidos</p><div className="mt-6 space-y-4">{Object.entries(byStatus).length ? Object.entries(byStatus).map(([key, value]) => { const count = Number(value) || 0; const total = Math.max(1, Number(orderKpis.total || orders.length || 1)); return <div key={key}><div className="mb-1.5 flex justify-between text-xs"><span className="font-medium text-slate-600">{statusLabels[key] || key}</span><span className="font-semibold text-slate-900">{count}</span></div><div className="h-2 rounded-full bg-slate-100"><div style={{ width: `${Math.min(100, count / total * 100)}%` }} className="h-full rounded-full bg-blue-400" /></div></div> }) : <Empty />}</div></Card></div><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-slate-100 p-5"><div><h3 className="section-title">Pedidos recientes</h3><p className="muted">Última actividad recibida</p></div><button onClick={() => onSection('orders')} className="link-button">Ver todos <ChevronRight className="size-3.5" /></button></div><OrderTable orders={orders.slice(0, 6)} /></Card></div>
}

function Orders({ orders, drivers, onReload, onStatus, onAssign }: { orders: Order[]; drivers: AdminUser[]; onReload: () => void; onStatus: (order: Order, status: string) => void; onAssign: (order: Order, driverId: string) => void }) { const [query, setQuery] = useState(''); const [status, setStatus] = useState(''); const filtered = useMemo(() => orders.filter(o => (!status || o.status === status) && `${o.id} ${o.user_full_name || ''} ${o.user_email || ''}`.toLowerCase().includes(query.toLowerCase())), [orders, query, status]); return <div className="space-y-5"><PageTitle title="Pedidos y asignaciones" description="Estados y asignaciones persistidas por FastAPI." action={<button onClick={onReload} className="secondary-button"><RefreshCw className="size-4" />Actualizar</button>} /><Card className="overflow-hidden"><div className="flex flex-wrap gap-3 border-b border-slate-100 p-4"><div className="search-field"><Search className="size-4 text-slate-400" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar pedido o cliente…" /></div><select value={status} onChange={event => setStatus(event.target.value)} className="field max-w-48"><option value="">Todos los estados</option>{Object.entries(statusLabels).map(([key, value]) => <option key={key} value={key}>{value}</option>)}</select></div><OrderTable orders={filtered} drivers={drivers} onStatus={onStatus} onAssign={onAssign} /></Card></div> }

function ProductEditor({ product, onClose, onSaved }: { product: Product | null; onClose: () => void; onSaved: () => void }) { const [form, setForm] = useState<AnyRecord>(() => ({ name: product?.name || '', code: product?.code || '', category: product?.category || '', brand: product?.brand || '', price: product?.price ?? 0, price_retail: product?.price_retail ?? 0, cost: product?.cost ?? 0, stock: product?.stock ?? 0, min_stock: product?.min_stock ?? 0, active: product?.active !== false })); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const set = (key: string, value: any) => setForm((current: AnyRecord) => ({ ...current, [key]: value })); async function save(event: FormEvent) { event.preventDefault(); setSaving(true); setError(''); try { const payload = { ...form, price: Number(form.price), price_retail: Number(form.price_retail), cost: Number(form.cost), stock: Number(form.stock), min_stock: Number(form.min_stock) }; await apiFetch(product ? `/products/${product.id}` : '/products', { method: product ? 'PUT' : 'POST', body: JSON.stringify(payload) }); onSaved(); onClose() } catch (e) { setError(errorMessage(e, 'No se pudo guardar')) } finally { setSaving(false) } } return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/30 p-4"><Card className="max-h-[90vh] w-full max-w-xl overflow-y-auto p-6"><div className="flex items-center justify-between"><div><h3 className="section-title">{product ? 'Editar producto' : 'Nuevo producto'}</h3><p className="muted">Los cambios se guardan en el backend.</p></div><button onClick={onClose} className="icon-button"><X className="size-4" /></button></div><form onSubmit={save} className="mt-5 grid gap-4 sm:grid-cols-2">{[['name','Nombre'],['code','Código'],['category','Categoría'],['brand','Marca'],['price','Precio mayorista'],['price_retail','Precio minorista'],['cost','Costo'],['stock','Stock'],['min_stock','Stock mínimo']].map(([key, label]) => <label key={key} className="text-sm font-medium text-slate-700">{label}<input required={key === 'name'} type={['price','price_retail','cost','stock','min_stock'].includes(key) ? 'number' : 'text'} step="any" value={form[key]} onChange={event => set(key, event.target.value)} className="field mt-1.5" /></label>)}<label className="flex items-center gap-2 text-sm font-medium text-slate-700"><input type="checkbox" checked={form.active} onChange={event => set('active', event.target.checked)} />Producto activo</label>{error && <p className="sm:col-span-2 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>}<div className="flex justify-end gap-2 sm:col-span-2"><button type="button" onClick={onClose} className="secondary-button">Cancelar</button><button disabled={saving} className="primary-button">{saving && <Loader2 className="size-4 animate-spin" />}Guardar producto</button></div></form></Card></div> }

function Products({ products, inventoryOnly, onReload, onAutoCategorize, canAutoCategorize }: { products: Product[]; inventoryOnly?: boolean; onReload: () => void; onAutoCategorize?: () => void; canAutoCategorize?: boolean }) { const [query, setQuery] = useState(''); const [editor, setEditor] = useState<Product | null | undefined>(); const filtered = useMemo(() => products.filter(product => { const low = Number(product.stock || 0) <= Number(product.min_stock || 0); return (!inventoryOnly || low) && `${product.name} ${product.code || ''} ${product.category || ''}`.toLowerCase().includes(query.toLowerCase()) }), [products, inventoryOnly, query]); return <div className="space-y-5"><PageTitle title={inventoryOnly ? 'Inventario y stock' : 'Productos y catálogo'} description={inventoryOnly ? 'Productos por debajo del mínimo configurado.' : 'Catálogo conectado a los endpoints de productos.'} action={<div className="flex gap-2">{canAutoCategorize && <button onClick={onAutoCategorize} className="secondary-button">Auto-categorizar</button>}{!inventoryOnly ? <button onClick={() => setEditor(null)} className="primary-button"><Plus className="size-4" />Nuevo producto</button> : <button onClick={onReload} className="secondary-button"><RefreshCw className="size-4" />Actualizar</button>}</div>} /><Card className="overflow-hidden"><div className="border-b border-slate-100 p-4"><div className="search-field max-w-md"><Search className="size-4 text-slate-400" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar por nombre, código o categoría…" /></div></div><div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th /></tr></thead><tbody>{filtered.length ? filtered.map(product => { const low = Number(product.stock || 0) <= Number(product.min_stock || 0); return <tr key={product.id}><td><p className="font-semibold text-slate-800">{product.name}</p><p className="text-[11px] text-slate-400">{product.code || `ID ${product.id}`}{product.brand ? ` · ${product.brand}` : ''}</p></td><td className="text-slate-500">{product.category || '—'}</td><td className="font-semibold">{money(product.price)}</td><td><span className={low ? 'font-bold text-red-600' : 'font-semibold text-slate-700'}>{product.stock ?? 0}</span><span className="text-xs text-slate-400"> / mín. {product.min_stock ?? 0}</span></td><td><Pill tone={product.active === false ? 'gray' : low ? 'red' : 'green'}>{product.active === false ? 'Inactivo' : low ? 'Stock bajo' : 'Disponible'}</Pill></td><td><button onClick={() => setEditor(product)} className="link-button">Editar</button></td></tr> }) : <tr><td colSpan={6}><Empty /></td></tr>}</tbody></table></div></Card>{editor !== undefined && <ProductEditor product={editor} onClose={() => setEditor(undefined)} onSaved={onReload} />}</div> }

function Operations({ data }: { data: AnyRecord }) { const recommendations = asArray(data?.recommendations); const summary = data?.summary || {}; const orders = data?.kpis?.orders || {}; const drivers = data?.kpis?.drivers || {}; return <div className="space-y-5"><PageTitle title="Operaciones" description={summary.headline || 'Estado consolidado de pedidos, inventario y entregas.'} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Pedidos recibidos" value={String(orders.received ?? 0)} detail="Pedidos que ingresaron" icon={Bell} tone="amber" /><Metric label="Pendientes" value={String(orders.pending_attention ?? 0)} detail="Requieren atención" icon={ClipboardList} tone="blue" /><Metric label="Entregados hoy" value={String(orders.delivered_today ?? 0)} detail="Actividad del día" icon={Check} /><Metric label="Repartidores online" value={String(drivers.online ?? 0)} detail={`${drivers.total ?? 0} registrados`} icon={Truck} tone="violet" /></div><Card className="p-5"><h3 className="section-title">Recomendaciones operativas</h3><p className="muted">Priorizadas por el backend.</p>{recommendations.length ? <div className="mt-4 grid gap-3 md:grid-cols-2">{recommendations.map((item, i) => <div key={i} className="rounded-xl border border-slate-200 p-4"><Pill tone={item.priority === 'critical' ? 'red' : item.priority === 'high' ? 'amber' : 'blue'}>{item.priority || 'info'}</Pill><p className="mt-3 font-semibold text-slate-800">{item.title || item.headline || item.message || 'Revisar operación'}</p><p className="mt-1 text-sm text-slate-500">{item.detail || item.description || item.action || ''}</p></div>)}</div> : <Empty message="No hay recomendaciones activas." />}</Card></div> }

function loadGoogleMaps() { if (!mapsKey) return Promise.reject(new Error('Falta NEXT_PUBLIC_GOOGLE_MAPS_API_KEY en el build del frontend.')); if (typeof window === 'undefined') return Promise.reject(new Error('Google Maps sólo se carga en el navegador.')); if (window.google?.maps) return Promise.resolve(window.google.maps); if (window.__distriarGoogleMapsPromise) return window.__distriarGoogleMapsPromise; window.__distriarGoogleMapsPromise = new Promise((resolve, reject) => { const callbackName = '__distriarMapsReady'; (window as any)[callbackName] = () => { delete (window as any)[callbackName]; resolve(window.google?.maps) }; const script = document.createElement('script'); script.id = 'distriar-google-maps'; script.async = true; script.defer = true; script.src = `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(mapsKey)}&loading=async&callback=${callbackName}&v=weekly`; script.onerror = () => { delete (window as any)[callbackName]; reject(new Error('No se pudo cargar Google Maps. Verificá la clave, las restricciones y Maps JavaScript API.')) }; document.head.appendChild(script) }); return window.__distriarGoogleMapsPromise }

function DriverMap({ locations }: { locations: AnyRecord[] }) { const container = useRef<HTMLDivElement>(null); const map = useRef<any>(null); const markers = useRef<any[]>([]); const [mapError, setMapError] = useState(''); const [mapReady, setMapReady] = useState(false); useEffect(() => { let cancelled = false; if (!mapsKey) { setMapError('Falta NEXT_PUBLIC_GOOGLE_MAPS_API_KEY en Render. El mapa queda visible, pero no puede dibujarse sin una clave pública restringida.'); return } void loadGoogleMaps().then(maps => { if (cancelled || !container.current) return; map.current = new maps.Map(container.current, { center: { lat: -32.883, lng: -68.84 }, zoom: 12, mapTypeControl: false, streetViewControl: false }); setMapReady(true); setMapError('') }).catch(error => { if (!cancelled) setMapError(error instanceof Error ? error.message : 'Google Maps no disponible.') }); return () => { cancelled = true; markers.current.forEach(marker => marker.setMap(null)); markers.current = [] } }, []); useEffect(() => { if (!mapReady || !map.current || !window.google?.maps) return; markers.current.forEach(marker => marker.setMap(null)); markers.current = locations.filter(location => Number.isFinite(Number(location.lat)) && Number.isFinite(Number(location.lon))).map(location => new window.google.maps.Marker({ map: map.current, position: { lat: Number(location.lat), lng: Number(location.lon) }, title: location.driver_name || location.driver_username || 'Repartidor' })) }, [locations, mapReady]); return <div className="relative min-h-[420px] overflow-hidden rounded-xl bg-slate-100"><div ref={container} className="absolute inset-0" />{mapError && <div className="absolute inset-x-4 top-4 rounded-xl border border-amber-200 bg-white/95 p-3 text-sm text-amber-800 shadow-sm">{mapError}</div>}{!locations.length && <div className="pointer-events-none absolute inset-x-4 bottom-4 rounded-xl bg-white/90 p-3 text-sm text-slate-600 shadow-sm">Mapa listo. No hay ubicaciones recientes para mostrar.</div>}</div> }

function Drivers({ users, locations, orders, zones, onReload, onAutoAssign, onInspect }: { users: AdminUser[]; locations: AnyRecord[]; orders: Order[]; zones: string[]; onReload: () => void; onAutoAssign: (driverId: string) => void; onInspect: (driver: AdminUser) => void }) { const drivers = users.filter(user => user.role === 'repartidor'); const [selected, setSelected] = useState(''); const live = new Map(locations.map(location => [String(location.driver_id || location.driver_username), location])); return <div className="space-y-5"><PageTitle title="Repartidores y mapa" description="Ubicaciones reales de /admin/driver-locations, actualizadas periódicamente." action={<button onClick={onReload} className="secondary-button"><RefreshCw className="size-4" />Actualizar</button>} /><div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><Card className="p-3"><DriverMap locations={locations} /></Card><Card className="p-5"><h3 className="section-title">Equipo de reparto</h3><p className="muted">{locations.length} ubicaciones vigentes · {drivers.length} repartidores visibles.</p><div className="mt-4 space-y-3">{drivers.length ? drivers.map(driver => { const point = live.get(String(driver.id)) || live.get(driver.username); return <div key={driver.id} className="rounded-xl bg-slate-50 p-3"><div className="flex items-center gap-3"><span className="flex size-9 items-center justify-center rounded-full bg-emerald-100 text-xs font-bold text-emerald-700">{(driver.full_name || driver.username).slice(0, 2).toUpperCase()}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-slate-800">{driver.full_name || driver.username}</p><p className="truncate text-xs text-slate-500">{driver.zone || 'Sin zona'}</p></div><Pill tone={point ? 'green' : 'gray'}>{point ? 'En línea' : 'Sin ubicación'}</Pill></div><div className="mt-2 flex gap-2"><button className="link-button" onClick={() => onInspect(driver)}>Ver actividad</button><a className="link-button" target="_blank" rel="noreferrer" href={point ? `https://www.google.com/maps?q=${point.lat},${point.lon}` : '#'} aria-disabled={!point}>Abrir mapa</a></div></div> }) : <Empty message="No hay repartidores visibles en este rubro." />}</div></Card></div><Card className="p-5"><div className="flex items-center gap-2"><Route className="size-5 text-emerald-600" /><div><h3 className="section-title">Asignación automática de rutas</h3><p className="muted">Usa /admin/routes/auto-assign y persiste repartidor, ruta y orden.</p></div></div><div className="mt-4 flex flex-wrap gap-3"><select value={selected} onChange={event => setSelected(event.target.value)} className="field max-w-sm"><option value="">Seleccioná un repartidor</option>{drivers.map(driver => <option key={driver.id} value={driver.id}>{driver.full_name || driver.username} · {driver.zone || 'sin zona'}</option>)}</select><button disabled={!selected} onClick={() => onAutoAssign(selected)} className="primary-button">Asignar pedidos preparados</button></div><p className="mt-3 text-xs text-slate-500">{orders.filter(order => ['preparado', 'enviado'].includes(String(order.status))).length} pedidos en etapa de reparto cargados. Zonas backend: {zones.length ? zones.join(', ') : 'no disponibles'}.</p></Card></div> }

function Sales({ sales }: { sales: AnyRecord }) { const rows = asArray(sales?.top_products); return <div className="space-y-5"><PageTitle title="Ventas y estadísticas" description="Agregados calculados por FastAPI para el período seleccionado." /><div className="grid gap-4 sm:grid-cols-3"><Metric label="Facturación" value={money(sales?.revenue)} detail={`${sales?.days || 30} días`} icon={CircleDollarSign} /><Metric label="Pedidos" value={String(sales?.orders || 0)} detail={`Muestra: ${sales?.sample_size || 0}`} icon={ShoppingCart} tone="blue" /><Metric label="Ticket promedio" value={money(sales?.avg_ticket)} detail="Total / pedidos" icon={ClipboardList} tone="amber" /></div><Card className="p-5"><h3 className="section-title">Productos más vendidos</h3><p className="muted">Fuente: /admin/sales/stats</p>{rows.length ? <div className="mt-4 divide-y divide-slate-100">{rows.map((row, i) => <div key={i} className="flex items-center justify-between py-3 text-sm"><span className="font-medium text-slate-700">{row.name || row.product_name || `Producto ${row.id || ''}`}</span><span className="font-semibold text-slate-900">{row.qty || row.quantity || 0} unidades</span></div>)}</div> : <Empty />}</Card></div> }

function Customers({ executive }: { executive: AnyRecord }) { const rows = asArray(executive?.top_customers); return <div className="space-y-5"><PageTitle title="Clientes y cuentas" description="Resumen de clientes derivado de los pedidos y estadísticas existentes." /><Card className="overflow-hidden"><div className="border-b border-slate-100 p-5"><h3 className="section-title">Clientes con mayor actividad</h3><p className="muted">No se crea una segunda fuente de clientes en el navegador.</p></div>{rows.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Cliente</th><th>Email</th><th>Pedidos</th><th>Facturación</th></tr></thead><tbody>{rows.map((row, i) => <tr key={i}><td className="font-semibold">{row.name || 'Cliente'}</td><td className="text-slate-500">{row.email || '—'}</td><td>{row.orders || 0}</td><td className="font-semibold">{money(row.revenue)}</td></tr>)}</tbody></table></div> : <Empty message="No hay actividad de clientes en el período." />}</Card></div> }
function Promotions({ promotions, consumos, onReload }: { promotions: AnyRecord[]; consumos: AnyRecord[]; onReload: () => void }) { return <div className="space-y-5"><PageTitle title="Promociones y consumos" description="Configuración conectada a /api/promos y /api/consumos." action={<button onClick={onReload} className="secondary-button"><RefreshCw className="size-4" />Actualizar</button>} /><div className="grid gap-5 xl:grid-cols-2"><Card className="p-5"><h3 className="section-title">Imágenes promocionales</h3><p className="muted">{promotions.length} seleccionadas para el carrusel.</p>{promotions.length ? <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3">{promotions.map((promo, i) => <a key={i} href={promo.url} target="_blank" rel="noreferrer" className="overflow-hidden rounded-xl border border-slate-200"><img src={promo.url} alt={promo.alt || 'Promoción'} className="aspect-square w-full object-cover" /></a>)}</div> : <Empty message="No hay promociones seleccionadas." />}</Card><Card className="p-5"><h3 className="section-title">Consumo inmediato</h3><p className="muted">{consumos.length} productos configurados.</p>{consumos.length ? <div className="mt-4 divide-y divide-slate-100">{consumos.map((item, i) => <div key={i} className="flex items-center justify-between py-3 text-sm"><span className="font-medium text-slate-700">Producto #{item.id}</span><Pill tone="amber">{item.discount}% · {item.qty || 0} u.</Pill></div>)}</div> : <Empty message="No hay consumos configurados." />}</Card></div></div> }

function SettingsView({ currentUser, scope, users, branches, zones, onReload }: { currentUser: AdminUser; scope: string; users: AdminUser[]; branches: AnyRecord[]; zones: string[]; onReload: () => void }) { const isOwner = currentUser.role === 'owner'; const [message, setMessage] = useState(''); const [form, setForm] = useState<AnyRecord>({ username: '', password: '', full_name: '', role: 'repartidor', business_scope: scope, zone: '' }); const [branch, setBranch] = useState<AnyRecord>({ name: '', street: '', street_number: '', lat: '', lon: '', business_scope: scope }); const [drafts, setDrafts] = useState<AnyRecord>({}); const [saving, setSaving] = useState(false); const setFormValue = (key: string, value: any) => setForm((current: AnyRecord) => ({ ...current, [key]: value })); const setBranchValue = (key: string, value: any) => setBranch((current: AnyRecord) => ({ ...current, [key]: value })); const draftFor = (user: AdminUser) => drafts[user.id] || { business_scope: user.business_scope || scope, zone: user.zone || '' }; async function createUser(event: FormEvent) { event.preventDefault(); setSaving(true); setMessage(''); try { await apiFetch('/admin/users', { method: 'POST', businessScope: scope, body: JSON.stringify({ ...form, business_scope: scope }) }); setForm({ username: '', password: '', full_name: '', role: 'repartidor', business_scope: scope, zone: '' }); setMessage('Usuario creado y persistido.'); onReload() } catch (error) { setMessage(errorMessage(error, 'No se pudo crear el usuario.')) } finally { setSaving(false) } } async function updateUser(user: AdminUser) { const draft = draftFor(user); setSaving(true); setMessage(''); try { const payload = user.role === 'repartidor' ? { zone: draft.zone, ...(isOwner ? { business_scope: draft.business_scope } : {}) } : { business_scope: draft.business_scope }; await apiFetch(`/admin/users/${user.id}`, { method: 'PATCH', businessScope: scope, body: JSON.stringify(payload) }); setMessage('Cambios de usuario persistidos.'); onReload() } catch (error) { setMessage(errorMessage(error, 'No se pudo actualizar el usuario.')) } finally { setSaving(false) } } async function deleteUser(user: AdminUser) { if (!isOwner || !window.confirm(`¿Eliminar a ${user.username}? Esta acción usa DELETE /admin/users/${user.id}.`)) return; setSaving(true); setMessage(''); try { await apiFetch(`/admin/users/${user.id}`, { method: 'DELETE', businessScope: scope }); setMessage('Usuario eliminado.'); onReload() } catch (error) { setMessage(errorMessage(error, 'No se pudo eliminar el usuario.')) } finally { setSaving(false) } } async function createBranch(event: FormEvent) { event.preventDefault(); setSaving(true); setMessage(''); try { await apiFetch('/admin/branches', { method: 'POST', businessScope: scope, body: JSON.stringify({ ...branch, lat: Number(branch.lat), lon: Number(branch.lon), business_scope: scope }) }); setBranch({ name: '', street: '', street_number: '', lat: '', lon: '', business_scope: scope }); setMessage('Sucursal creada y persistida.'); onReload() } catch (error) { setMessage(errorMessage(error, 'No se pudo crear la sucursal.')) } finally { setSaving(false) } } async function deleteBranch(item: AnyRecord) { if (!isOwner || !window.confirm(`¿Eliminar la sucursal ${item.name}?`)) return; setSaving(true); setMessage(''); try { await apiFetch(`/admin/branches/${item.id}`, { method: 'DELETE', businessScope: scope }); setMessage('Sucursal eliminada.'); onReload() } catch (error) { setMessage(errorMessage(error, 'No se pudo eliminar la sucursal.')) } finally { setSaving(false) } } return <div className="space-y-5"><PageTitle title="Usuarios y sucursales" description="Acciones visibles según las capacidades reales del backend." action={<button onClick={onReload} className="secondary-button"><RefreshCw className="size-4" />Actualizar</button>} />{message && <div className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-700">{message}</div>}<div className="grid gap-5 xl:grid-cols-2"><Card className="overflow-hidden"><div className="border-b border-slate-100 p-5"><h3 className="section-title">Usuarios administrativos</h3><p className="muted">{users.length} usuarios visibles en el rubro. No existe endpoint de desactivación: el backend sólo expone DELETE.</p></div><div className="divide-y divide-slate-100">{users.map(user => { const draft = draftFor(user); return <div key={user.id} className="space-y-3 p-4"><div className="flex items-center gap-3"><span className="flex size-9 items-center justify-center rounded-full bg-slate-100 text-xs font-bold text-slate-600"><UserRound className="size-4" /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{user.full_name || user.username}</p><p className="text-xs text-slate-500">@{user.username} · {user.role} · {user.business_scope || scope}</p></div><Pill tone={user.is_active ? 'green' : 'gray'}>{user.is_active ? 'Activo' : 'Inactivo'}</Pill></div>{user.role !== 'owner' && <div className="flex flex-wrap items-end gap-2"><label className="text-xs font-semibold text-slate-500">Rubro<select disabled={!isOwner} value={draft.business_scope} onChange={event => setDrafts(current => ({ ...current, [user.id]: { ...draft, business_scope: event.target.value } }))} className="field mt-1"><option value="mayorista">Mayorista</option><option value="minorista">Minorista</option></select></label>{user.role === 'repartidor' && <label className="text-xs font-semibold text-slate-500">Zona<select value={draft.zone} onChange={event => setDrafts(current => ({ ...current, [user.id]: { ...draft, zone: event.target.value } }))} className="field mt-1"><option value="">Seleccionar zona</option>{zones.map(zone => <option key={zone} value={zone}>{zone}</option>)}</select></label>}<button disabled={saving} onClick={() => void updateUser(user)} className="secondary-button"><Save className="size-4" />Guardar</button>{isOwner && <button disabled={saving} onClick={() => void deleteUser(user)} className="secondary-button text-red-700"><Trash2 className="size-4" />Eliminar</button>}</div>}</div> })}{!users.length && <Empty />}</div></Card><div className="space-y-5">{isOwner && <Card className="p-5"><div className="flex items-center gap-2"><UserPlus className="size-5 text-emerald-600" /><div><h3 className="section-title">Crear usuario</h3><p className="muted">El backend no permite crear owners adicionales.</p></div></div><form onSubmit={createUser} className="mt-4 grid gap-3 sm:grid-cols-2"><Field label="Usuario" value={form.username} onChange={value => setFormValue('username', value)} required /><Field label="Contraseña" value={form.password} onChange={value => setFormValue('password', value)} type="password" required /><Field label="Nombre" value={form.full_name} onChange={value => setFormValue('full_name', value)} /><label className="text-sm font-medium text-slate-700">Rol<select value={form.role} onChange={event => setFormValue('role', event.target.value)} className="field mt-1.5"><option value="repartidor">Repartidor</option><option value="admin">Admin</option></select></label>{form.role === 'repartidor' && <label className="text-sm font-medium text-slate-700 sm:col-span-2">Zona<select required value={form.zone} onChange={event => setFormValue('zone', event.target.value)} className="field mt-1.5"><option value="">Seleccionar zona</option>{zones.map(zone => <option key={zone} value={zone}>{zone}</option>)}</select></label>}<button disabled={saving} className="primary-button sm:col-span-2">Crear usuario</button></form></Card>}<Card className="overflow-hidden"><div className="border-b border-slate-100 p-5"><div className="flex items-center gap-2"><Building2 className="size-5 text-emerald-600" /><div><h3 className="section-title">Sucursales</h3><p className="muted">{branches.length} sucursales disponibles. El backend expone listar, crear y eliminar; no expone PATCH.</p></div></div></div><div className="divide-y divide-slate-100">{branches.map(item => <div key={item.id} className="flex items-center gap-3 p-4"><MapPin className="size-4 text-emerald-600" /><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{item.name}</p><p className="text-xs text-slate-500">{item.address_line || `${item.street} ${item.street_number}`} · {item.lat}, {item.lon}</p></div>{isOwner && <button onClick={() => void deleteBranch(item)} className="link-button text-red-700"><Trash2 className="size-4" /></button>}</div>)}{!branches.length && <Empty />}</div>{isOwner && <form onSubmit={createBranch} className="grid gap-3 border-t border-slate-100 p-5 sm:grid-cols-2"><Field label="Nombre" value={branch.name} onChange={value => setBranchValue('name', value)} required /><Field label="Calle" value={branch.street} onChange={value => setBranchValue('street', value)} required /><Field label="Número" value={branch.street_number} onChange={value => setBranchValue('street_number', value)} required /><Field label="Latitud Mendoza" value={branch.lat} onChange={value => setBranchValue('lat', value)} type="number" required /><Field label="Longitud Mendoza" value={branch.lon} onChange={value => setBranchValue('lon', value)} type="number" required /><button disabled={saving} className="primary-button sm:col-span-2">Crear sucursal</button></form>}</Card></div></div></div> }

function OwnerTools({ scope }: { scope: string }) { const [data, setData] = useState<AnyRecord>({}); const [message, setMessage] = useState(''); async function read(path: string) { setMessage(''); try { setData({ endpoint: path, payload: await apiFetch<AnyRecord>(path, { businessScope: scope }) }) } catch (error) { setMessage(errorMessage(error, 'No se pudo consultar la herramienta.')) } } return <Card className="p-5"><div className="flex items-center gap-2"><Settings className="size-5 text-emerald-600" /><div><h3 className="section-title">Herramientas heredadas de consulta</h3><p className="muted">Lecturas reales del resumen PWA, push y entregas del backend.</p></div></div><div className="mt-4 flex flex-wrap gap-2"><button onClick={() => void read('/admin/resumen-semanal-pwa?days=7')} className="secondary-button">Resumen PWA</button><button onClick={() => void read('/admin/push/config')} className="secondary-button">Config. push</button><button onClick={() => void read('/admin/deliveries?limit=100')} className="secondary-button">Historial entregas</button></div>{message && <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{message}</p>}{data.endpoint && <pre className="mt-4 max-h-72 overflow-auto rounded-xl bg-slate-950 p-4 text-xs text-emerald-200">{JSON.stringify(data, null, 2)}</pre>}</Card> }

function OwnerConsole({ scope }: { scope: string }) { const [status, setStatus] = useState<AnyRecord>({}); const [count, setCount] = useState('10'); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false); const refresh = useCallback(async () => { try { setStatus(await apiFetch<AnyRecord>('/admin/stress-test/status', { businessScope: scope })) } catch (error) { setMessage(errorMessage(error, 'No se pudo consultar la consola.')) } }, [scope]); useEffect(() => { void refresh() }, [refresh]); useEffect(() => { const phase = String(status.phase || '').toLowerCase(); if (!['creating', 'running'].includes(phase)) return; const timer = window.setInterval(() => void refresh(), 2500); return () => window.clearInterval(timer) }, [status.phase, refresh]); async function call(path: string, body?: AnyRecord) { setBusy(true); setMessage(''); try { setStatus(await apiFetch<AnyRecord>(path, { method: 'POST', businessScope: scope, body: body ? JSON.stringify(body) : undefined })) } catch (error) { setMessage(errorMessage(error, 'La consola rechazó la operación.')) } finally { setBusy(false) } } return <div className="space-y-5"><PageTitle title="Consola del owner" description="Implementa las operaciones reales del stress test QA del panel anterior." action={<button onClick={() => void refresh()} className="secondary-button"><RefreshCw className="size-4" />Consultar estado</button>} />{message && <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{message}</div>}<Card className="p-5"><div className="flex flex-wrap items-end gap-3"><Field label="Cantidad de pedidos QA" value={count} onChange={setCount} type="number" /><button disabled={busy} onClick={() => void call('/admin/stress-test/start', { count: Number(count) })} className="primary-button">Iniciar stress test</button><button disabled={busy} onClick={() => void call('/admin/stress-test/ready')} className="secondary-button">.ready</button><button disabled={busy} onClick={() => void call('/admin/stress-test/cancel')} className="secondary-button text-red-700">/cancel</button></div><p className="mt-3 text-xs text-slate-500">Estas acciones crean datos QA según la lógica del backend. No se expone /debug/clear en la UI para evitar borrados accidentales.</p></Card><Card className="p-5"><h3 className="section-title">Estado real</h3><pre className="mt-4 max-h-96 overflow-auto rounded-xl bg-slate-950 p-4 text-xs text-emerald-200">{JSON.stringify(status, null, 2)}</pre></Card><OwnerTools scope={scope} /></div> }

export default function Page() {
  const [user, setUser] = useState<AdminUser | null>(null); const [scope, setScope] = useState('mayorista'); const [active, setActive] = useState<SectionId>('dashboard'); const [collapsed, setCollapsed] = useState(false); const [mobileNav, setMobileNav] = useState(false); const [loading, setLoading] = useState(false); const [error, setError] = useState(''); const [orders, setOrders] = useState<Order[]>([]); const [products, setProducts] = useState<Product[]>([]); const [operations, setOperations] = useState<AnyRecord>({}); const [executive, setExecutive] = useState<AnyRecord>({}); const [sales, setSales] = useState<AnyRecord>({}); const [users, setUsers] = useState<AdminUser[]>([]); const [branches, setBranches] = useState<AnyRecord[]>([]); const [locations, setLocations] = useState<AnyRecord[]>([]); const [zones, setZones] = useState<string[]>([]); const [promotions, setPromotions] = useState<AnyRecord[]>([]); const [consumos, setConsumos] = useState<AnyRecord[]>([])
  const load = useCallback(async (section: SectionId = active) => { if (!user || section === 'owner-console') return; setLoading(true); setError(''); const options = { businessScope: scope }; try { if (section === 'dashboard' || section === 'operations') { const results = await Promise.allSettled([apiFetch<AnyRecord>('/admin/operations/overview?days=30', options), apiFetch<AnyRecord>('/admin/resumen-ejecutivo?days=30', options), apiFetch<AnyRecord>('/admin/sales/stats?days=30', options), apiFetch<Order[]>('/admin/orders?limit=100', options)]); const labels = ['operaciones', 'resumen ejecutivo', 'ventas', 'pedidos']; const failures: string[] = []; results.forEach((result, index) => { if (result.status === 'rejected') failures.push(`${labels[index]}: ${errorMessage(result.reason, 'falló')}`); else if (index === 0) setOperations(result.value); else if (index === 1) setExecutive(result.value); else if (index === 2) setSales(result.value); else setOrders(asArray(result.value)) }); if (failures.length) setError(`Carga parcial del panel: ${failures.join(' · ')}`) } else if (section === 'orders') { const results = await Promise.allSettled([apiFetch<Order[]>('/admin/orders?limit=500', options), apiFetch<AdminUser[]>('/admin/users', options)]); if (results[0].status === 'fulfilled') setOrders(asArray(results[0].value)); else setError(`Pedidos: ${errorMessage(results[0].reason, 'no se pudieron cargar')}`); if (results[1].status === 'fulfilled') setUsers(asArray(results[1].value)); } else if (section === 'catalog' || section === 'inventory') { const result = await apiFetch<AnyRecord>('/products/paged?skip=0&limit=200&sort=name', options); setProducts(asArray(result.items)) } else if (section === 'sales') setSales(await apiFetch<AnyRecord>('/admin/sales/stats?days=30', options)); else if (section === 'customers') setExecutive(await apiFetch<AnyRecord>('/admin/resumen-ejecutivo?days=30', options)); else if (section === 'drivers') { const results = await Promise.allSettled([apiFetch<AdminUser[]>('/admin/users', options), apiFetch<AnyRecord[]>('/admin/driver-locations', options), apiFetch<Order[]>('/admin/orders?limit=500', options), apiFetch<AnyRecord>('/admin/zones', options)]); const failures: string[] = []; if (results[0].status === 'fulfilled') setUsers(asArray(results[0].value)); else failures.push(`repartidores: ${errorMessage(results[0].reason, 'falló')}`); if (results[1].status === 'fulfilled') setLocations(asArray(results[1].value)); else failures.push(`ubicaciones: ${errorMessage(results[1].reason, 'falló')}`); if (results[2].status === 'fulfilled') setOrders(asArray(results[2].value)); if (results[3].status === 'fulfilled') setZones(asArray(results[3].value.zones)); if (failures.length) setError(`Carga parcial de repartidores: ${failures.join(' · ')}`) } else if (section === 'promotions') { const results = await Promise.allSettled([apiFetch<AnyRecord[]>('/api/promos', options), apiFetch<AnyRecord[]>('/api/consumos', options)]); if (results[0].status === 'fulfilled') setPromotions(asArray(results[0].value)); if (results[1].status === 'fulfilled') setConsumos(asArray(results[1].value)); if (results.some(result => result.status === 'rejected')) setError('No se pudo cargar una parte de promociones/consumos.') } else if (section === 'settings') { const results = await Promise.allSettled([apiFetch<AdminUser[]>('/admin/users', options), apiFetch<AnyRecord[]>('/admin/branches', options), apiFetch<AnyRecord>('/admin/zones', options)]); if (results[0].status === 'fulfilled') setUsers(asArray(results[0].value)); else setError(`Usuarios: ${errorMessage(results[0].reason, 'no se pudieron cargar')}`); if (results[1].status === 'fulfilled') setBranches(asArray(results[1].value)); else setError(`Sucursales: ${errorMessage(results[1].reason, 'no se pudieron cargar')}`); if (results[2].status === 'fulfilled') setZones(asArray(results[2].value.zones)) } } catch (e) { if (e instanceof ApiError && e.status === 401) { setAdminToken(null); setUser(null) } else setError(`Error de carga: ${errorMessage(e, 'no se pudieron cargar los datos')}`) } finally { setLoading(false) } }, [active, scope, user])
  useEffect(() => { const token = getAdminToken(); if (!token) return; apiFetch<AdminUser>('/admin/auth/me').then(loggedUser => { setUser(loggedUser); setScope(loggedUser.active_business_scope || loggedUser.business_scope || 'mayorista') }).catch(() => setAdminToken(null)) }, [])
  useEffect(() => { if (user) void load(active) }, [user, active, scope])
  useEffect(() => { if (!user || active !== 'drivers') return; const timer = window.setInterval(() => void load('drivers'), 30000); return () => window.clearInterval(timer) }, [user, active, load])
  useEffect(() => { if (!user || (active !== 'dashboard' && active !== 'catalog' && active !== 'inventory')) return; let socket: WebSocket | null = null; try { socket = new WebSocket(websocketUrl()); socket.onmessage = () => void load(active) } catch { /* HTTP remains the source of truth. */ } return () => socket?.close() }, [user, active, load])
  async function updateOrderStatus(order: Order, status: string) { try { await apiFetch(`/orders/${order.id}/status`, { method: 'PATCH', body: JSON.stringify({ status }), headers: { 'X-Actor': user?.username || '' } }); await load('orders') } catch (e) { setError(errorMessage(e, 'No se pudo actualizar el pedido')) } }
  async function assignOrder(order: Order, driverId: string) { if (!driverId) { setError('El backend no expone desasignación desde este endpoint.'); return } try { await apiFetch(`/admin/orders/${order.id}/assign`, { method: 'PATCH', businessScope: scope, body: JSON.stringify({ driver_id: Number(driverId) }) }); await load(active === 'drivers' ? 'drivers' : 'orders') } catch (e) { setError(errorMessage(e, 'No se pudo asignar el pedido')) } }
  async function autoAssign(driverId: string) { try { await apiFetch('/admin/routes/auto-assign', { method: 'POST', businessScope: scope, body: JSON.stringify({ driver_id: Number(driverId), include_assigned: true, customer_type: scope }) }); await load('drivers') } catch (e) { setError(errorMessage(e, 'No se pudo generar la ruta')) } }
  async function inspectDriver(driver: AdminUser) { try { const insight = await apiFetch<AnyRecord>(`/admin/driver-insights?driver_id=${encodeURIComponent(driver.id)}&customer_type=${encodeURIComponent(scope)}`, { businessScope: scope }); setError(`Actividad de ${driver.full_name || driver.username}: ${JSON.stringify(insight)}`) } catch (e) { setError(errorMessage(e, 'No se pudo consultar la actividad del repartidor')) } }
  async function autoCategorize() { try { await apiFetch('/admin/products/auto-categorize', { method: 'POST', businessScope: scope, body: JSON.stringify({ overwrite_category: false }) }); await load('catalog') } catch (e) { setError(errorMessage(e, 'No se pudo auto-categorizar')) } }
  if (!user) return <Login onLoggedIn={loggedUser => { setUser(loggedUser); setScope(loggedUser.active_business_scope || loggedUser.business_scope || 'mayorista') }} />
  const visibleNav = nav.filter(item => !item.ownerOnly || user.role === 'owner'); const groups = [...new Set(visibleNav.map(item => item.group))]; const currentLabel = visibleNav.find(item => item.id === active)?.label || 'Resumen'; const drivers = users.filter(item => item.role === 'repartidor')
  return <div className="flex min-h-screen bg-slate-50 text-slate-900"><aside className={`fixed inset-y-0 left-0 z-40 flex w-64 flex-col border-r border-slate-200 bg-white transition-transform lg:static lg:translate-x-0 ${collapsed ? 'lg:w-[78px]' : ''} ${mobileNav ? 'translate-x-0' : '-translate-x-full'}`}><div className={`flex h-[72px] items-center border-b border-slate-100 ${collapsed ? 'justify-center' : 'gap-3 px-5'}`}><span className="flex size-9 items-center justify-center rounded-xl bg-emerald-600 font-bold text-white">D</span>{!collapsed && <div><p className="font-bold">Distri<span className="text-emerald-600">Ar</span></p><p className="text-[9px] font-semibold uppercase tracking-widest text-slate-400">Panel admin</p></div>}</div><nav className="flex-1 overflow-y-auto px-3 py-5">{groups.map(group => <div key={group} className="mb-5"><p className={`mb-2 px-3 text-[10px] font-bold tracking-widest text-slate-400 ${collapsed ? 'text-center' : ''}`}>{collapsed ? '•' : group}</p>{visibleNav.filter(item => item.group === group).map(item => <button key={item.id} title={collapsed ? item.label : undefined} onClick={() => { setActive(item.id); setMobileNav(false) }} className={`mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-xs font-medium transition ${active === item.id ? 'bg-emerald-50 font-semibold text-emerald-700' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'} ${collapsed ? 'justify-center' : ''}`}><item.icon className="size-4 shrink-0" />{!collapsed && <span className="truncate">{item.label}</span>}</button>)}</div>)}</nav><div className="border-t border-slate-100 p-3"><button onClick={() => { setAdminToken(null); setUser(null) }} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-xs font-medium text-slate-500 hover:bg-red-50 hover:text-red-700 ${collapsed ? 'justify-center' : ''}`}><LogOut className="size-4" />{!collapsed && 'Cerrar sesión'}</button><button onClick={() => setCollapsed(value => !value)} className="mt-1 flex w-full justify-center rounded-lg py-2 text-slate-400 hover:bg-slate-50">{collapsed ? <PanelLeftOpen className="size-4" /> : <PanelLeftClose className="size-4" />}</button></div></aside><main className="min-w-0 flex-1"><header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-slate-200 bg-white/95 px-4 backdrop-blur sm:px-6 lg:px-8"><div className="flex items-center gap-3"><button onClick={() => setMobileNav(value => !value)} className="icon-button lg:hidden"><Menu className="size-5" /></button><div><div className="hidden items-center gap-2 text-[11px] text-slate-400 sm:flex"><span>Inicio</span><ChevronRight className="size-3" /><span>Panel</span></div><h1 className="text-lg font-bold">{currentLabel}</h1></div></div><div className="flex items-center gap-3"><label className="hidden items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-xs text-slate-400 md:flex"><span>Rubro</span><select value={scope} onChange={event => setScope(event.target.value)} className="bg-transparent font-semibold text-slate-700 outline-none"><option value="mayorista">Mayorista</option><option value="minorista">Minorista</option></select></label><button onClick={() => void load(active)} className="icon-button" title="Actualizar"><RefreshCw className={`size-4 ${loading ? 'animate-spin' : ''}`} /></button><div className="flex items-center gap-2 border-l border-slate-100 pl-3"><span className="flex size-9 items-center justify-center rounded-full bg-emerald-100 text-xs font-bold text-emerald-700">{(user.full_name || user.username).slice(0, 2).toUpperCase()}</span><div className="hidden sm:block"><p className="text-xs font-semibold">{user.full_name || user.username}</p><p className="text-[11px] text-slate-400">{user.role}</p></div></div></div></header><div className="mx-auto max-w-[1480px] p-4 sm:p-6 lg:p-8">{error && <div className="mb-5 flex items-start justify-between gap-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700"><span className="break-words">{error}</span><button onClick={() => setError('')}><X className="size-4" /></button></div>}{loading && !orders.length && !products.length && <div className="mb-5 flex items-center gap-2 text-sm text-slate-500"><Loader2 className="size-4 animate-spin" />Cargando información real…</div>}{active === 'dashboard' && <Dashboard data={{ ...operations, sales }} orders={orders} onSection={setActive} />}{active === 'operations' && <Operations data={operations} />}{active === 'orders' && <Orders orders={orders} drivers={drivers} onReload={() => void load('orders')} onStatus={updateOrderStatus} onAssign={assignOrder} />}{active === 'catalog' && <Products products={products} onReload={() => void load('catalog')} onAutoCategorize={autoCategorize} canAutoCategorize={user.role === 'owner' || user.role === 'admin'} />}{active === 'inventory' && <Products products={products} inventoryOnly onReload={() => void load('inventory')} />}{active === 'sales' && <Sales sales={sales} />}{active === 'customers' && <Customers executive={executive} />}{active === 'drivers' && <Drivers users={users} locations={locations} orders={orders} zones={zones} onReload={() => void load('drivers')} onAutoAssign={autoAssign} onInspect={inspectDriver} />}{active === 'promotions' && <Promotions promotions={promotions} consumos={consumos} onReload={() => void load('promotions')} />}{active === 'settings' && <SettingsView currentUser={user} scope={scope} users={users} branches={branches} zones={zones} onReload={() => void load('settings')} />}{active === 'owner-console' && user.role === 'owner' && <OwnerConsole scope={scope} />}</div></main></div>
}
function PromoAssets({ scope, onReload }: { scope: string; onReload: () => void }) {
  const [items, setItems] = useState<AnyRecord[]>([]); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState('')
  const load = useCallback(async () => { setBusy(true); setError(''); try { setItems(asArray(await apiFetch<AnyRecord[]>('/api/uploads', { businessScope: scope }))) } catch (value) { setError(errorMessage(value, 'No se pudieron cargar las imágenes promocionales.')) } finally { setBusy(false) } }, [scope])
  useEffect(() => { void load() }, [load])
  async function upload(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const input = event.currentTarget.elements.namedItem('promo-file') as HTMLInputElement | null; const file = input?.files?.[0]; if (!file) { setError('Seleccioná una imagen antes de subirla.'); return }; setBusy(true); setMessage(''); setError(''); try { const body = new FormData(); body.append('file', file); await apiFetch('/api/promos', { method: 'POST', businessScope: scope, body }); event.currentTarget.reset(); setMessage('Imagen subida y guardada.'); await load(); onReload() } catch (value) { setError(errorMessage(value, 'No se pudo subir la imagen.')) } finally { setBusy(false) } }
  async function select(item: AnyRecord) { setBusy(true); setMessage(''); setError(''); try { await apiFetch(`/api/promos/select?name=${encodeURIComponent(String(item.name || ''))}`, { method: 'POST', businessScope: scope }); setMessage('Imagen seleccionada para el carrusel.'); await load(); onReload() } catch (value) { setError(errorMessage(value, 'No se pudo seleccionar la imagen.')) } finally { setBusy(false) } }
  async function deselect(item: AnyRecord) { setBusy(true); setMessage(''); setError(''); try { await apiFetch(`/api/promos/select/${encodeURIComponent(String(item.name || ''))}`, { method: 'DELETE', businessScope: scope }); setMessage('Imagen retirada del carrusel.'); await load(); onReload() } catch (value) { setError(errorMessage(value, 'No se pudo retirar la imagen.')) } finally { setBusy(false) } }
  async function remove(item: AnyRecord) { if (!window.confirm(`¿Eliminar la imagen ${item.name || ''}? Esta acción no se puede deshacer.`)) return; setBusy(true); setMessage(''); setError(''); try { await apiFetch(`/api/promos/${encodeURIComponent(String(item.name || ''))}`, { method: 'DELETE', businessScope: scope }); setMessage('Imagen eliminada.'); await load(); onReload() } catch (value) { setError(errorMessage(value, 'No se pudo eliminar la imagen.')) } finally { setBusy(false) } }
  return <Card className="p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="section-title">Biblioteca de imágenes promocionales</h3><p className="muted">Consulta, carga, selección y eliminación usando los endpoints existentes.</p></div><button onClick={() => void load()} disabled={busy} className="secondary-button"><RefreshCw className={`size-4 ${busy ? 'animate-spin' : ''}`} />Actualizar</button></div><form onSubmit={upload} className="mt-4 flex flex-wrap items-end gap-3"><label className="text-sm font-medium text-slate-700">Archivo<input name="promo-file" type="file" accept="image/png,image/jpeg,image/webp,image/gif" className="field mt-1.5" /></label><button disabled={busy} className="primary-button">{busy && <Loader2 className="size-4 animate-spin" />}Subir imagen</button></form>{message && <p className="mt-3 rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-700">{message}</p>}{error && <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>}{busy && !items.length && <div className="mt-4 flex items-center gap-2 text-sm text-slate-500"><Loader2 className="size-4 animate-spin" />Cargando biblioteca…</div>}{items.length ? <div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{items.map(item => <div key={String(item.name)} className="overflow-hidden rounded-xl border border-slate-200"><img src={item.url} alt={item.alt || item.name || 'Promoción'} className="aspect-video w-full bg-slate-100 object-cover" /><div className="space-y-3 p-3"><div className="flex items-center justify-between gap-2"><p className="truncate text-xs font-semibold text-slate-700" title={item.name}>{item.name}</p><Pill tone={item.selected ? 'green' : 'gray'}>{item.selected ? 'Seleccionada' : 'No seleccionada'}</Pill></div><div className="flex flex-wrap gap-2">{item.selected ? <button disabled={busy} onClick={() => void deselect(item)} className="secondary-button">Quitar del carrusel</button> : <button disabled={busy} onClick={() => void select(item)} className="secondary-button">Seleccionar</button>}<button disabled={busy} onClick={() => void remove(item)} className="link-button text-red-700"><Trash2 className="size-4" />Eliminar</button></div></div></div>)}</div> : !busy && <Empty message="No hay imágenes promocionales cargadas." />}</Card>
}

function ConsumosEditor({ scope, items, onReload }: { scope: string; items: AnyRecord[]; onReload: () => void }) {
  const [drafts, setDrafts] = useState<AnyRecord[]>([]); const [saving, setSaving] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState('')
  useEffect(() => { setDrafts(items.map(item => ({ id: item.id, discount: item.discount ?? 0, qty: item.qty ?? 0, type: item.type || 'percent' }))) }, [items])
  function update(index: number, key: string, value: string) { setDrafts(current => current.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item)) }
  async function save() { setSaving(true); setMessage(''); setError(''); try { await apiFetch('/api/consumos', { method: 'POST', businessScope: scope, body: JSON.stringify(drafts.map(item => ({ ...item, id: Number(item.id), discount: Number(item.discount), qty: Number(item.qty) }))) }); setMessage('Consumos guardados y persistidos.'); onReload() } catch (value) { setError(errorMessage(value, 'No se pudieron guardar los consumos.')) } finally { setSaving(false) } }
  return <Card className="p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="section-title">Consumo inmediato</h3><p className="muted">Configuración editable mediante POST /api/consumos.</p></div><button onClick={() => setDrafts(current => [...current, { id: '', discount: 0, qty: 0, type: 'percent' }])} className="secondary-button"><Plus className="size-4" />Agregar</button></div>{drafts.length ? <div className="mt-4 space-y-3">{drafts.map((item, index) => <div key={index} className="grid gap-2 rounded-xl bg-slate-50 p-3 sm:grid-cols-[1fr_1fr_1fr_auto]"><Field label="Producto ID" value={item.id} onChange={value => update(index, 'id', value)} type="number" required /><Field label="Descuento %" value={item.discount} onChange={value => update(index, 'discount', value)} type="number" required /><Field label="Cantidad" value={item.qty} onChange={value => update(index, 'qty', value)} type="number" required /><button onClick={() => setDrafts(current => current.filter((_, itemIndex) => itemIndex !== index))} className="link-button self-end text-red-700"><Trash2 className="size-4" />Quitar</button></div>)}</div> : <Empty message="No hay consumos configurados." />}{message && <p className="mt-3 rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-700">{message}</p>}{error && <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>}<button onClick={() => void save()} disabled={saving || !drafts.length} className="primary-button mt-4">{saving && <Loader2 className="size-4 animate-spin" />}Guardar consumos</button></Card>
}

function PromotionsFunctional({ scope, promotions, consumos, onReload }: { scope: string; promotions: AnyRecord[]; consumos: AnyRecord[]; onReload: () => void }) { return <div className="space-y-5"><PageTitle title="Promociones y consumos" description="Gestión funcional conectada a los endpoints existentes." action={<button onClick={onReload} className="secondary-button"><RefreshCw className="size-4" />Actualizar</button>} /><PromoAssets scope={scope} onReload={onReload} /><ConsumosEditor scope={scope} items={consumos} onReload={onReload} />{promotions.length > 0 && <Card className="p-5"><h3 className="section-title">Carrusel activo</h3><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3">{promotions.map((promo, index) => <img key={index} src={promo.url} alt={promo.alt || 'Promoción'} className="aspect-video rounded-xl object-cover" />)}</div></Card>}</div> }
;(Promotions as any) = PromotionsExtended
function NextZoneAssignments({ scope, users, zones }: { scope: string; users: AdminUser[]; zones: string[] }) {
  const drivers = users.filter(user => user.role === 'repartidor'); const [rows, setRows] = useState<AnyRecord[]>([]); const [drafts, setDrafts] = useState<AnyRecord>({}); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState('')
  const load = useCallback(async () => { setBusy(true); setError(''); try { setRows(asArray(await apiFetch<AnyRecord[]>('/admin/driver-next-zones', { businessScope: scope }))) } catch (value) { setError(errorMessage(value, 'No se pudieron cargar las asignaciones del día siguiente.')) } finally { setBusy(false) } }, [scope])
  useEffect(() => { void load() }, [load])
  const assigned = new Map(rows.map(row => [String(row.driver_id), row]))
  async function save(driver: AdminUser) { setBusy(true); setMessage(''); setError(''); try { const zone = String(drafts[driver.id] ?? assigned.get(String(driver.id))?.zone ?? ''); await apiFetch(`/admin/users/${driver.id}/next-zone`, { method: 'PATCH', businessScope: scope, body: JSON.stringify({ zone: zone || null }) }); setMessage(`Zona del día siguiente guardada para ${driver.full_name || driver.username}.`); await load() } catch (value) { setError(errorMessage(value, 'No se pudo guardar la zona del día siguiente.')) } finally { setBusy(false) } }
  return <Card className="p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="section-title">Asignaciones del día siguiente</h3><p className="muted">Persistidas mediante PATCH /admin/users/:id/next-zone.</p></div><button onClick={() => void load()} disabled={busy} className="secondary-button"><RefreshCw className={`size-4 ${busy ? 'animate-spin' : ''}`} />Actualizar</button></div>{error && <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>}{message && <p className="mt-3 rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-700">{message}</p>}{drivers.length ? <div className="mt-4 grid gap-3 md:grid-cols-2">{drivers.map(driver => { const current = assigned.get(String(driver.id)); return <div key={driver.id} className="flex flex-wrap items-end gap-2 rounded-xl bg-slate-50 p-3"><div className="min-w-40 flex-1"><p className="text-sm font-semibold">{driver.full_name || driver.username}</p><p className="text-xs text-slate-500">Actual: {driver.zone || 'sin zona'} · Próxima: {current?.zone || 'sin asignar'}</p></div><select value={drafts[driver.id] ?? current?.zone ?? ''} onChange={event => setDrafts(value => ({ ...value, [driver.id]: event.target.value }))} className="field min-w-40"><option value="">Sin asignar</option>{zones.map(zone => <option key={zone} value={zone}>{zone}</option>)}</select><button disabled={busy} onClick={() => void save(driver)} className="secondary-button"><Save className="size-4" />Guardar</button></div> })}</div> : <Empty message="No hay repartidores visibles en este rubro." />}</Card>
}

const LegacyDrivers = Drivers
function DriversFunctional(props: { users: AdminUser[]; locations: AnyRecord[]; orders: Order[]; zones: string[]; onReload: () => void; onAutoAssign: (driverId: string) => void; onInspect: (driver: AdminUser) => void }) { return <div className="space-y-5"><LegacyDrivers {...props} /><NextZoneAssignments scope={props.users[0]?.business_scope || 'mayorista'} users={props.users} zones={props.zones} /></div> }
;(Drivers as any) = DriversFunctional
function PromotionRules({ scope }: { scope: string }) {
  const [items, setItems] = useState<AnyRecord[]>([]); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState('')
  const load = useCallback(async () => { setBusy(true); setError(''); try { const payload = await apiFetch<any>('/promotions', { businessScope: scope }); setItems(asArray(payload?.promotions ?? payload)) } catch (value) { setError(errorMessage(value, 'No se pudieron cargar las promociones.')) } finally { setBusy(false) } }, [scope])
  useEffect(() => { void load() }, [load])
  function update(index: number, key: string, value: string) { setItems(current => current.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item)) }
  async function save() { setBusy(true); setMessage(''); setError(''); try { const payload = items.map(item => ({ ...item, id: item.id || `promo_${Date.now()}`, name: String(item.name || '').trim(), description: String(item.description || ''), productIds: String(item.productIdsText ?? item.productIds ?? '').split(',').map(value => Number(value.trim())).filter(value => Number.isFinite(value)), type: item.type || 'percent', value: item.value === '' ? null : Number(item.value), valid_until: item.valid_until || null })).filter(item => item.name); await apiFetch('/promotions', { method: 'POST', businessScope: scope, body: JSON.stringify(payload) }); setItems(payload); setMessage('Promociones guardadas y persistidas.'); await load() } catch (value) { setError(errorMessage(value, 'No se pudieron guardar las promociones.')) } finally { setBusy(false) } }
  return <Card className="p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="section-title">Reglas de promociones</h3><p className="muted">Alta, edición y eliminación mediante el POST completo de /promotions.</p></div><div className="flex gap-2"><button onClick={() => setItems(current => [...current, { name: '', description: '', productIdsText: '', type: 'percent', value: '', valid_until: '' }])} className="secondary-button"><Plus className="size-4" />Nueva</button><button onClick={() => void load()} disabled={busy} className="secondary-button"><RefreshCw className={`size-4 ${busy ? 'animate-spin' : ''}`} />Actualizar</button></div></div>{error && <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>}{message && <p className="mt-3 rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-700">{message}</p>}{items.length ? <div className="mt-4 space-y-3">{items.map((item, index) => <div key={String(item.id || index)} className="grid gap-2 rounded-xl bg-slate-50 p-3 md:grid-cols-2 xl:grid-cols-5"><Field label="Nombre" value={item.name} onChange={value => update(index, 'name', value)} required /><Field label="Descripción" value={item.description} onChange={value => update(index, 'description', value)} /><Field label="Producto IDs" value={item.productIdsText ?? asArray(item.productIds).join(', ')} onChange={value => update(index, 'productIdsText', value)} placeholder="1, 2, 3" /><Field label="Valor %" value={item.value ?? ''} onChange={value => update(index, 'value', value)} type="number" /><label className="text-sm font-medium text-slate-700">Válida hasta<input type="datetime-local" value={item.valid_until ? String(item.valid_until).slice(0, 16) : ''} onChange={event => update(index, 'valid_until', event.target.value)} className="field mt-1.5" /></label><button onClick={() => setItems(current => current.filter((_, itemIndex) => itemIndex !== index))} className="link-button justify-self-start text-red-700"><Trash2 className="size-4" />Quitar</button></div>)}</div> : <Empty message="No hay reglas de promociones configuradas." />}<button onClick={() => void save()} disabled={busy} className="primary-button mt-4">{busy && <Loader2 className="size-4 animate-spin" />}Guardar promociones</button></Card>
}

function PromotionsExtended(props: { scope: string; promotions: AnyRecord[]; consumos: AnyRecord[]; onReload: () => void }) { return <div className="space-y-5"><PromotionsFunctional {...props} /><PromotionRules scope={props.scope} /></div> }
